A('libas', 'آداب اللباس والزينة', 'اللباس نعمة للستر والزينة، وله آداب.',
  ['التسمية عند اللبس، والبدء باليمين، والخلع بالشمال.', 'يحرم على الرجال لبس الحرير والذهب، ويحرم الإسبال على وجه الخيلاء.', 'لا يتشبه الرجال بالنساء ولا النساء بالرجال.', 'دعاء لبس الجديد: «اللهم لك الحمد أنت كسوتنيه...».'],
  [('﴿يا بني آدم قد أنزلنا عليكم لباساً يواري سوآتكم وريشاً ولباس التقوى ذلك خير﴾', 'الأعراف: ٢٦.')],
  [('عند لبس الثوب يبدأ بـ:', ['اليمين', 'الشمال'], 0, '')],
  [('riyad', 'كتاب اللباس')])
A('marid', 'عيادة المريض والضيافة', 'عيادة المريض حق للمسلم على أخيه، وإكرام الضيف من الإيمان.',
  ['«حق المسلم على المسلم خمس: رد السلام، وعيادة المريض، واتباع الجنائز، وإجابة الدعوة، وتشميت العاطس» متفق عليه.', 'دعاء المريض: «لا بأس، طهور إن شاء الله».', '«من كان يؤمن بالله واليوم الآخر فليكرم ضيفه»، والضيافة ثلاثة أيام.', 'تشميت العاطس: إذا حمد الله قيل له: يرحمك الله، فيقول: يهديكم الله ويصلح بالكم.'],
  [('«لا بأس، طهور إن شاء الله»', 'رواه البخاري.')],
  [('من حقوق المسلم على المسلم:', ['عيادة المريض', 'إعطاؤه ماله'], 0, ''), ('ماذا يقول من شُمّت؟', ['يهديكم الله ويصلح بالكم', 'لا شيء'], 0, '')],
  [('riyad', 'كتاب عيادة المريض'), ('adab', 'المريض')])
A('walidayn', 'بر الوالدين وصلة الرحم', 'بر الوالدين من أعظم القربات بعد التوحيد، وصلة الرحم سبب لسعة الرزق وطول العمر.',
  ['قُرن حق الوالدين بحق الله: ﴿وقضى ربك ألا تعبدوا إلا إياه وبالوالدين إحساناً﴾.', 'لا تقل لهما «أف»، وادعُ لهما في حياتهما وبعد موتهما.', '«من أحب أن يبسط له في رزقه وينسأ له في أثره فليصل رحمه» متفق عليه.', 'وفي التطبيق قسم «زاد الوالدين» لتربية الأبناء.'],
  [('﴿وقل رب ارحمهما كما ربياني صغيراً﴾', 'الإسراء: ٢٤.')],
  [('من ثمرات صلة الرحم:', ['البسط في الرزق', 'لا ثمرة لها'], 0, '')],
  [('riyad', 'بر الوالدين'), ('adab', 'بر الوالدين')])
